INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10701, 'នៅលើបន្ទាត់ចំនួនដេក កូអរដោនេនៃចំណុចគល់ \(O\) និងចំណុចឯកតា \(E\) គឺ៖', NULL, '["\\(O(1), \\; E(0)\\)", "\\(O(0), \\; E(1)\\)", "\\(O(0), \\; E(-1)\\)", "\\(O(-1), \\; E(1)\\)"]', 1, NULL, 1, 'mcq', 'តាមនិយមន័យនៃបន្ទាត់ចំនួន ចំណុចគល់ត្រូវគ្នានឹងចំនួន 0 ហើយចំណុចឯកតាត្រូវគ្នានឹងចំនួន 1 គឺ \(O(0)\) និង \(E(1)\)។', 'ចំនួន', 'easy', 1, '10', 'ចំនួន', 'ជំពូកទី 2 : តក្កវិទ្យា សំណុំ និងចំនួន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10702, 'ចំពោះគ្រប់ចំនួនពិត \(a < 0\) តម្លៃដាច់ខាត \(|a|\) ស្មើនឹង៖', NULL, '["\\(0\\)", "\\(a^2\\)", "\\(-a\\)", "\\(a\\)"]', 2, NULL, 1, 'mcq', 'តាមនិយមន័យនៃតម្លៃដាច់ខាត បើ \(a < 0\) នោះ \(|a| = -a\) (ជាចំនួនវិជ្ជមាន)។', 'ចំនួន', 'easy', 1, '10', 'ចំនួន', 'ជំពូកទី 2 : តក្កវិទ្យា សំណុំ និងចំនួន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10703, 'គណនាតម្លៃកន្សោម \(|-7| + |3| - |-4|\)៖', NULL, '["\\(6\\)", "\\(8\\)", "\\(-8\\)", "\\(14\\)"]', 0, NULL, 1, 'mcq', '\(|-7| = 7, \; |3| = 3, \; |-4| = 4 \implies 7 + 3 - 4 = 6\)។', 'ចំនួន', 'easy', 1, '10', 'ចំនួន', 'ជំពូកទី 2 : តក្កវិទ្យា សំណុំ និងចំនួន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10704, 'សំណុំនៃចំនួនគត់ធម្មជាតិតាងដោយអក្សរ \(\mathbb{N}\) គឺ៖', NULL, '["\\(\\mathbb{N} = \\{2, 4, 6, 8, \\dots\\}\\)", "\\(\\mathbb{N} = \\{1, 2, 3, 4, \\dots\\}\\)", "\\(\\mathbb{N} = \\{0, 1, 2, 3, \\dots\\}\\)", "\\(\\mathbb{N} = \\{\\dots, -2, -1, 0, 1, 2, \\dots\\}\\)"]', 1, NULL, 1, 'mcq', 'សំណុំចំនួនគត់ធម្មជាតិតាងដោយ \(\mathbb{N} = \{1, 2, 3, \dots\}\)។ ចំណែក \(\{0, 1, 2, \dots\}\) ជាសំណុំ \(\mathbb{W}\)។', 'ចំនួន', 'easy', 1, '10', 'ចំនួន', 'ជំពូកទី 2 : តក្កវិទ្យា សំណុំ និងចំនួន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10705, 'ចំនួនសនិទានគឺជាចំនួនដែលអាចសរសេរជាទម្រង់ណា?', NULL, '["\\(m \\times 10^n \\quad (n < 0)\\)", "\\(\\dfrac{m}{n} \\quad (m, n \\in \\mathbb{Z}, \\; n \\neq 0)\\)", "\\(\\sqrt{m} \\quad (m \\in \\mathbb{Z})\\)", "\\(\\dfrac{m}{n} \\quad (m, n \\in \\mathbb{N})\\)"]', 1, NULL, 1, 'mcq', 'តាមនិយមន័យ ចំនួនសនិទានគឺជាចំនួនដែលអាចសរសេរជាទម្រង់ប្រភាគ \(\dfrac{m}{n}\) ដែល \(m, n \in \mathbb{Z}\) និង \(n \neq 0\)។', 'ចំនួន', 'easy', 1, '10', 'ចំនួន', 'ជំពូកទី 2 : តក្កវិទ្យា សំណុំ និងចំនួន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10706, 'ក្នុងចំណោមចំនួនខាងក្រោម តើចំនួនណាជា «ចំនួនអសនិទាន»?', NULL, '["\\(\\sqrt{9}\\)", "\\(\\dfrac{4}{7}\\)", "\\(\\sqrt{3}\\)", "\\(0.25\\)"]', 2, NULL, 1, 'mcq', '\(\sqrt{3} \approx 1.732\dots\) ជាចំនួនទសភាគអនន្តគ្មានខួប ដូច្នេះជាចំនួនអសនិទាន។ ចំណែក \(0.25 = 1/4\), \(4/7\) និង \(\sqrt{9} = 3\) សុទ្ធតែជាចំនួនសនិទាន។', 'ចំនួន', 'easy', 1, '10', 'ចំនួន', 'ជំពូកទី 2 : តក្កវិទ្យា សំណុំ និងចំនួន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10707, 'សម្រួលកន្សោមរ៉ាឌីកាល់ \(\sqrt{12}\)៖', NULL, '["\\(2\\sqrt{3}\\)", "\\(6\\)", "\\(3\\sqrt{2}\\)", "\\(4\\sqrt{3}\\)"]', 0, NULL, 1, 'mcq', '\(\sqrt{12} = \sqrt{4 \times 3} = \sqrt{2^2 \times 3} = 2\sqrt{3}\)។', 'ចំនួន', 'easy', 1, '10', 'ចំនួន', 'ជំពូកទី 2 : តក្កវិទ្យា សំណុំ និងចំនួន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10708, 'គណនាផលចែករ៉ាឌីកាល់ \(\dfrac{\sqrt{32}}{\sqrt{2}}\)៖', NULL, '["\\(16\\)", "\\(8\\)", "\\(2\\sqrt{2}\\)", "\\(4\\)"]', 3, NULL, 1, 'mcq', '\(\dfrac{\sqrt{32}}{\sqrt{2}} = \sqrt{\dfrac{32}{2}} = \sqrt{16} = 4\)។', 'ចំនួន', 'easy', 1, '10', 'ចំនួន', 'ជំពូកទី 2 : តក្កវិទ្យា សំណុំ និងចំនួន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10709, 'ទម្រង់ពន្លាតនៃចំនួន \(432\) ក្នុងប្រព័ន្ធរបាប់គោល 10 គឺ៖', NULL, '["\\(4 \\times 10^3 + 3 \\times 10^2 + 2\\)", "\\(4 \\times 10^2 + 3 \\times 10^1 + 2\\)", "\\(43 \\times 10 + 2\\)", "\\(4 \\times 10^2 + 3 \\times 10^2 + 2\\)"]', 1, NULL, 1, 'mcq', 'ខ្ទង់រយគឺ 4, ខ្ទង់ដប់គឺ 3, ខ្ទង់រាយគឺ 2 ដូច្នេះ \(432 = 4 \times 10^2 + 3 \times 10^1 + 2\)។', 'ចំនួន', 'easy', 1, '10', 'ចំនួន', 'ជំពូកទី 2 : តក្កវិទ្យា សំណុំ និងចំនួន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10710, 'ប្រព័ន្ធរបាប់គោល 2 (Binary) ប្រើប្រាស់និមិត្តសញ្ញាលេខប៉ុន្មានតួ?', NULL, '["២ តួ (លេខ 0 និងលេខ 1)", "៨ តួ (លេខ 0 ដល់លេខ 7)", "១០ តួ (លេខ 0 ដល់លេខ 9)", "១៦ តួ (លេខ 0 ដល់លេខ 15)"]', 0, NULL, 1, 'mcq', 'ប្រព័ន្ធរបាប់គោល 2 ប្រើតែលេខពីរគត់គឺ 0 និង 1 សម្រាប់តំណាងគ្រប់តម្លៃទាំងអស់។', 'ចំនួន', 'easy', 1, '10', 'ចំនួន', 'ជំពូកទី 2 : តក្កវិទ្យា សំណុំ និងចំនួន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10711, 'ដោះស្រាយសមីការ \(|x - 3| = 4\) ក្នុងសំណុំចំនួនពិត៖', NULL, '["\\(x = 7 \\text{ ឬ } x = -1\\)", "\\(x = 1 \\text{ ឬ } x = -7\\)", "\\(x = 7 \\text{ តែមួយគត់}\\)", "\\(x = 7 \\text{ ឬ } x = 1\\)"]', 0, NULL, 2, 'mcq', '\(|x - 3| = 4 \iff x - 3 = 4\) ឬ \(x - 3 = -4 \implies x = 7\) ឬ \(x = -1\)។', 'ចំនួន', 'medium', 1, '10', 'ចំនួន', 'ជំពូកទី 2 : តក្កវិទ្យា សំណុំ និងចំនួន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10712, 'បើ \(a = -5\) តើតម្លៃនៃ \(\sqrt{a^2}\) ស្មើនឹងប៉ុន្មាន?', NULL, '["\\(25\\)", "\\(-5\\)", "\\(\\pm 5\\)", "\\(5\\)"]', 3, NULL, 2, 'mcq', '\(\sqrt{a^2} = |a| = |-5| = 5\)។ រ៉ាឌីកាល់ការេនៃចំនួនពិតមិនអាចអវិជ្ជមានឡើយ។', 'ចំនួន', 'medium', 1, '10', 'ចំនួន', 'ជំពូកទី 2 : តក្កវិទ្យា សំណុំ និងចំនួន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10713, 'គណនាកន្សោម \(\sqrt{20} - \sqrt{45} + \sqrt{80}\)៖', NULL, '["\\(2\\sqrt{5}\\)", "\\(-\\sqrt{5}\\)", "\\(3\\sqrt{5}\\)", "\\(5\\sqrt{5}\\)"]', 2, NULL, 2, 'mcq', '\(\sqrt{20} = 2\sqrt{5}, \; \sqrt{45} = 3\sqrt{5}, \; \sqrt{80} = 4\sqrt{5} \implies (2 - 3 + 4)\sqrt{5} = 3\sqrt{5}\)។', 'ចំនួន', 'medium', 1, '10', 'ចំនួន', 'ជំពូកទី 2 : តក្កវិទ្យា សំណុំ និងចំនួន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10714, 'គណនាផលគុណ \((\sqrt{3} - \sqrt{2})^2\)៖', NULL, '["\\(1 - 2\\sqrt{6}\\)", "\\(5 - \\sqrt{6}\\)", "\\(1\\)", "\\(5 - 2\\sqrt{6}\\)"]', 3, NULL, 2, 'mcq', '\((\sqrt{3} - \sqrt{2})^2 = (\sqrt{3})^2 - 2\sqrt{3}\sqrt{2} + (\sqrt{2})^2 = 3 - 2\sqrt{6} + 2 = 5 - 2\sqrt{6}\)។', 'ចំនួន', 'medium', 1, '10', 'ចំនួន', 'ជំពូកទី 2 : តក្កវិទ្យា សំណុំ និងចំនួន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10715, 'ប្រៀបធៀបចំនួនវិជ្ជមានពីរ \(2\sqrt{7}\) និង \(3\sqrt{3}\)៖', NULL, '["\\(2\\sqrt{7} > 3\\sqrt{3}\\)", "\\(\\text{មិនអាចប្រៀបធៀបបាន}\\)", "\\(2\\sqrt{7} = 3\\sqrt{3}\\)", "\\(2\\sqrt{7} < 3\\sqrt{3}\\)"]', 0, NULL, 2, 'mcq', '\((2\sqrt{7})^2 = 4 \times 7 = 28\) និង \((3\sqrt{3})^2 = 9 \times 3 = 27\)។ ដោយ \(28 > 27 \implies 2\sqrt{7} > 3\sqrt{3}\)។', 'ចំនួន', 'medium', 1, '10', 'ចំនួន', 'ជំពូកទី 2 : តក្កវិទ្យា សំណុំ និងចំនួន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10716, 'បំបាត់រ៉ាឌីកាល់ពីភាគបែងនៃប្រភាគ \(\dfrac{6}{\sqrt{3}}\)៖', NULL, '["\\(\\dfrac{\\sqrt{3}}{2}\\)", "\\(3\\sqrt{3}\\)", "\\(2\\sqrt{3}\\)", "\\(6\\sqrt{3}\\)"]', 2, NULL, 2, 'mcq', '\(\dfrac{6}{\sqrt{3}} = \dfrac{6\sqrt{3}}{(\sqrt{3})^2} = \dfrac{6\sqrt{3}}{3} = 2\sqrt{3}\)។', 'ចំនួន', 'medium', 1, '10', 'ចំនួន', 'ជំពូកទី 2 : តក្កវិទ្យា សំណុំ និងចំនួន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10717, 'បំបាត់រ៉ាឌីកាល់ពីភាគបែងនៃ \(\dfrac{\sqrt{3}}{\sqrt{3} + \sqrt{2}}\)៖', NULL, '["\\(1 - \\sqrt{6}\\)", "\\(\\dfrac{3 - \\sqrt{6}}{5}\\)", "\\(3 + \\sqrt{6}\\)", "\\(3 - \\sqrt{6}\\)"]', 3, NULL, 2, 'mcq', 'គុណនឹងកន្សោមឆ្លាស់ \(\sqrt{3} - \sqrt{2}\)៖ \(\dfrac{\sqrt{3}(\sqrt{3}-\sqrt{2})}{(\sqrt{3})^2 - (\sqrt{2})^2} = \dfrac{3 - \sqrt{6}}{3 - 2} = 3 - \sqrt{6}\)។', 'ចំនួន', 'medium', 1, '10', 'ចំនួន', 'ជំពូកទី 2 : តក្កវិទ្យា សំណុំ និងចំនួន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10718, 'សម្រួលកន្សោមរ៉ាឌីកាល់ពីរជាន់ \(\sqrt{4 + 2\sqrt{3}}\)៖', NULL, '["\\(\\sqrt{3} - 1\\)", "\\(1 + \\sqrt{2}\\)", "\\(\\sqrt{3} + 1\\)", "\\(2 + \\sqrt{3}\\)"]', 2, NULL, 2, 'mcq', 'រក \(u, v\) ដែល \(u+v=4\) និង \(uv=3 \implies u=3, v=1\) នាំឱ្យ \(\sqrt{(\sqrt{3}+1)^2} = \sqrt{3} + 1\)។', 'ចំនួន', 'medium', 1, '10', 'ចំនួន', 'ជំពូកទី 2 : តក្កវិទ្យា សំណុំ និងចំនួន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10719, 'សម្រួលកន្សោមរ៉ាឌីកាល់ពីរជាន់ \(\sqrt{6 - 2\sqrt{8}}\)៖', NULL, '["\\(\\sqrt{6} - \\sqrt{8}\\)", "\\(2 - \\sqrt{2}\\)", "\\(2 + \\sqrt{2}\\)", "\\(\\sqrt{2} - 2\\)"]', 1, NULL, 2, 'mcq', 'រក \(u, v\) ដែល \(u+v=6\) និង \(uv=8 \implies u=4, v=2\) នាំឱ្យ \(\sqrt{(\sqrt{4}-\sqrt{2})^2} = \sqrt{4} - \sqrt{2} = 2 - \sqrt{2}\)។', 'ចំនួន', 'medium', 1, '10', 'ចំនួន', 'ជំពូកទី 2 : តក្កវិទ្យា សំណុំ និងចំនួន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10720, 'ចំនួនទសភាគខួប \(0.\overline{12} = 0.121212\dots\) ស្មើនឹងប្រភាគសនិទានណា?', NULL, '["\\(\\dfrac{4}{33}\\)", "\\(\\dfrac{1}{12}\\)", "\\(\\dfrac{12}{100}\\)", "\\(\\dfrac{2}{15}\\)"]', 0, NULL, 2, 'mcq', 'តាង \(x = 0.1212... \implies 100x = 12.1212... \implies 99x = 12 \implies x = 12/99 = 4/33\)។', 'ចំនួន', 'medium', 1, '10', 'ចំនួន', 'ជំពូកទី 2 : តក្កវិទ្យា សំណុំ និងចំនួន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10721, 'បំប្លែងចំនួន \(11\,011_2\) ទៅជាចំនួនក្នុងប្រព័ន្ធរបាប់គោល 10៖', NULL, '["\\(27\\)", "\\(29\\)", "\\(25\\)", "\\(23\\)"]', 0, NULL, 2, 'mcq', '\(11\,011_2 = 1(2^4) + 1(2^3) + 0(2^2) + 1(2^1) + 1(2^0) = 16 + 8 + 0 + 2 + 1 = 27\)។', 'ចំនួន', 'medium', 1, '10', 'ចំនួន', 'ជំពូកទី 2 : តក្កវិទ្យា សំណុំ និងចំនួន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10722, 'បំប្លែងចំនួន \(33_{10}\) ទៅជាចំនួនក្នុងប្រព័ន្ធរបាប់គោល 2៖', NULL, '["\\(110\\,001_2\\)", "\\(10\\,001_2\\)", "\\(100\\,001_2\\)", "\\(100\\,011_2\\)"]', 2, NULL, 2, 'mcq', '\(33 = 32 + 1 = 2^5 + 2^0 = 100\,001_2\)។', 'ចំនួន', 'medium', 1, '10', 'ចំនួន', 'ជំពូកទី 2 : តក្កវិទ្យា សំណុំ និងចំនួន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10723, 'គណនាផលបូកក្នុងប្រព័ន្ធគោល 2 ៖ \(1\,011_2 + 101_2\)៖', NULL, '["\\(10\\,000_2\\)", "\\(1\\,100_2\\)", "\\(10\\,010_2\\)", "\\(1\\,110_2\\)"]', 0, NULL, 2, 'mcq', '\(1\,011_2 = 11\) និង \(101_2 = 5 \implies 11 + 5 = 16 = 2^4 = 10\,000_2\)។', 'ចំនួន', 'medium', 1, '10', 'ចំនួន', 'ជំពូកទី 2 : តក្កវិទ្យា សំណុំ និងចំនួន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10724, 'គណនាផលដកក្នុងប្រព័ន្ធគោល 2 ៖ \(11\,001_2 - 1\,001_2\)៖', NULL, '["\\(11\\,000_2\\)", "\\(10\\,100_2\\)", "\\(10\\,000_2\\)", "\\(1\\,000_2\\)"]', 2, NULL, 2, 'mcq', '\(11\,001_2 = 25\) និង \(1\,001_2 = 9 \implies 25 - 9 = 16 = 10\,000_2\)។', 'ចំនួន', 'medium', 1, '10', 'ចំនួន', 'ជំពូកទី 2 : តក្កវិទ្យា សំណុំ និងចំនួន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10725, 'សម្រួលកន្សោមរ៉ាឌីកាល់ពីរជាន់ \(\sqrt{7 + \sqrt{24}}\)៖', NULL, '["\\(\\sqrt{5} + \\sqrt{2}\\)", "\\(\\sqrt{6} + 1\\)", "\\(\\sqrt{6} - 1\\)", "\\(2 + \\sqrt{3}\\)"]', 1, NULL, 3, 'mcq', '\(\sqrt{24} = \sqrt{4 \times 6} = 2\sqrt{6}\) នាំឱ្យកន្សោមទៅជា \(\sqrt{7 + 2\sqrt{6}} = \sqrt{(\sqrt{6}+1)^2} = \sqrt{6} + 1\)។', 'ចំនួន', 'hard', 1, '10', 'ចំនួន', 'ជំពូកទី 2 : តក្កវិទ្យា សំណុំ និងចំនួន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10726, 'សម្រួលកន្សោម \(\sqrt{3 - \sqrt{5}}\)៖', NULL, '["\\(\\sqrt{5} - \\sqrt{2}\\)", "\\(\\dfrac{\\sqrt{5} - 1}{2}\\)", "\\(\\dfrac{\\sqrt{10} + \\sqrt{2}}{2}\\)", "\\(\\dfrac{\\sqrt{10} - \\sqrt{2}}{2}\\)"]', 3, NULL, 3, 'mcq', '\(\sqrt{3 - \sqrt{5}} = \sqrt{\dfrac{6 - 2\sqrt{5}}{2}} = \dfrac{\sqrt{5} - 1}{\sqrt{2}} = \dfrac{\sqrt{10} - \sqrt{2}}{2}\)។', 'ចំនួន', 'hard', 1, '10', 'ចំនួន', 'ជំពូកទី 2 : តក្កវិទ្យា សំណុំ និងចំនួន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10727, 'គណនាតម្លៃនៃ \((\sqrt{7 + 2\sqrt{10}} - \sqrt{7 - 2\sqrt{10}})^2\)៖', NULL, '["\\(4\\sqrt{10}\\)", "\\(14\\)", "\\(8\\)", "\\(4\\)"]', 2, NULL, 3, 'mcq', '\(\sqrt{7 + 2\sqrt{10}} = \sqrt{5} + \sqrt{2}\) និង \(\sqrt{7 - 2\sqrt{10}} = \sqrt{5} - \sqrt{2}\) នាំឱ្យផលដកស្មើ \(2\sqrt{2}\)។ ការេនៃផលដកគឺ \((2\sqrt{2})^2 = 8\)។', 'ចំនួន', 'hard', 1, '10', 'ចំនួន', 'ជំពូកទី 2 : តក្កវិទ្យា សំណុំ និងចំនួន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10728, 'បំបាត់រ៉ាឌីកាល់ពីភាគបែងនៃ \(\dfrac{1}{1 + \sqrt{2} - \sqrt{3}}\)៖', NULL, '["\\(\\dfrac{\\sqrt{2} + 2 + \\sqrt{6}}{4}\\)", "\\(\\dfrac{1 + \\sqrt{2} + \\sqrt{3}}{2}\\)", "\\(\\dfrac{\\sqrt{6} - \\sqrt{2}}{4}\\)", "\\(\\dfrac{\\sqrt{2} + 2 - \\sqrt{6}}{4}\\)"]', 0, NULL, 3, 'mcq', 'គុណនឹង \((1+\sqrt{2})+\sqrt{3}\) បានភាគបែង \((1+\sqrt{2})^2 - 3 = 2\sqrt{2}\)។ គុណបន្តនឹង \(\sqrt{2}\) ទទួលបាន \(\dfrac{\sqrt{2} + 2 + \sqrt{6}}{4}\)។', 'ចំនួន', 'hard', 1, '10', 'ចំនួន', 'ជំពូកទី 2 : តក្កវិទ្យា សំណុំ និងចំនួន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10729, 'គេឱ្យ \(x = \dfrac{1}{\sqrt{7} - \sqrt{5}}\) និង \(y = \dfrac{1}{\sqrt{7} + \sqrt{5}}\)។ គណនាតម្លៃនៃ \(\dfrac{y}{x} + \dfrac{x}{y}\)៖', NULL, '["\\(12\\)", "\\(6\\)", "\\(24\\)", "\\(14\\)"]', 0, NULL, 3, 'mcq', '\(x = \dfrac{\sqrt{7}+\sqrt{5}}{2}, \; y = \dfrac{\sqrt{7}-\sqrt{5}}{2} \implies x+y = \sqrt{7}, \; xy = 1/2\)។ គេបាន \(\dfrac{x^2+y^2}{xy} = \dfrac{(x+y)^2 - 2xy}{xy} = \dfrac{7 - 1}{1/2} = 12\)។', 'ចំនួន', 'hard', 1, '10', 'ចំនួន', 'ជំពូកទី 2 : តក្កវិទ្យា សំណុំ និងចំនួន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10730, 'ប្រៀបធៀប និងគណនាផលដក \(123_{10} - 1\,101_2\) ជាចំនួនក្នុងប្រព័ន្ធគោល 10៖', NULL, '["\\(112\\)", "\\(108\\)", "\\(110\\)", "\\(120\\)"]', 2, NULL, 3, 'mcq', '\(1\,101_2 = 1(8) + 1(4) + 0(2) + 1(1) = 13\)។ ដូច្នេះផលដកគឺ \(123 - 13 = 110\)។', 'ចំនួន', 'hard', 1, '10', 'ចំនួន', 'ជំពូកទី 2 : តក្កវិទ្យា សំណុំ និងចំនួន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10731, 'បើ \(x\) ជាចំនួនពិតវិជ្ជមានដែលមានផ្នែកគត់ជាចំនួនពីរខ្ទង់ តើ \(x\) ផ្ទៀងផ្ទាត់វិសមភាពណា?', NULL, '["\\(10 \\le x < 100\\)", "\\(1 \\le x < 100\\)", "\\(10 < x < 99\\)", "\\(10 \\le x \\le 99\\)"]', 0, NULL, 3, 'mcq', 'ចំនួនពីរខ្ទង់តូចបំផុតគឺ 10 ហើយចំនួនបីខ្ទង់តូចបំផុតគឺ 100 ដូច្នេះផ្នែកគត់មានពីរខ្ទង់កាលណា \(10 \le x < 100\)។', 'ចំនួន', 'hard', 1, '10', 'ចំនួន', 'ជំពូកទី 2 : តក្កវិទ្យា សំណុំ និងចំនួន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10732, 'អង្គចងចាំកុំព្យូទ័រខ្នាត 16-bit អាចផ្ទុកលេខកូដគោលពីរពី \(0\,000\,000\,000\,000\,000_2\) ដល់ \(1\,111\,111\,111\,111\,111_2\)។ តើវាអាចតំណាងឱ្យតម្លៃផ្សេងគ្នាសរុបចំនួនប៉ុន្មាន?', NULL, '["\\(16\\,384\\)", "\\(65\\,535\\)", "\\(32\\,768\\)", "\\(65\\,536\\)"]', 3, NULL, 3, 'mcq', 'ចំនួនស្ថានភាពសរុបគឺ \(2^{16} = 65\,536\) ស្ថានភាពផ្សេងគ្នា (ពី 0 ដល់ 65535)។', 'ចំនួន', 'pisa', 1, '10', 'ចំនួន', 'ជំពូកទី 2 : តក្កវិទ្យា សំណុំ និងចំនួន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10733, 'នាឡិកាឌីជីថលប្រើប្រព័ន្ធលេខកូដគោលពីរ (BCD) សម្រាប់ខ្ទង់នីមួយៗ។ តើលេខ \(9\) ត្រូវតំណាងដោយកូដគោលពីរ 4-bit ណា?', NULL, '["\\(1\\,100_2\\)", "\\(0\\,111_2\\)", "\\(1\\,001_2\\)", "\\(1\\,010_2\\)"]', 2, NULL, 3, 'mcq', '\(9 = 8 + 1 = 1 \times 2^3 + 0 \times 2^2 + 0 \times 2^1 + 1 \times 2^0 = 1\,001_2\)។', 'ចំនួន', 'pisa', 1, '10', 'ចំនួន', 'ជំពូកទី 2 : តក្កវិទ្យា សំណុំ និងចំនួន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10734, 'អេក្រង់ទូរទស្សន៍មួយមានសមាមាត្របណ្តោយនិងទទឹង \(4:3\)។ បើទទឹងគឺ \(3x\text{ cm}\) និងបណ្តោយគឺ \(4x\text{ cm}\) នោះប្រវែងអង្កត់ទ្រូងអេក្រង់ស្មើនឹង៖', NULL, '["\\(\\sqrt{7}x\\text{ cm}\\)", "\\(7x\\text{ cm}\\)", "\\(12x\\text{ cm}\\)", "\\(5x\\text{ cm}\\)"]', 3, NULL, 3, 'mcq', 'តាមទ្រឹស្តីបទពីតាគ័រ \(d = \sqrt{(4x)^2 + (3x)^2} = \sqrt{16x^2 + 9x^2} = \sqrt{25x^2} = 5x\text{ cm}\)។', 'ចំនួន', 'pisa', 1, '10', 'ចំនួន', 'ជំពូកទី 2 : តក្កវិទ្យា សំណុំ និងចំនួន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10735, 'ខ្នាតរង្វាស់ល្បឿនអ៊ីនធឺណិតគិតជាគីឡូបៃ \(1\text{ KiB} = 2^{10}\text{ Bytes}\) និងគិតជាប្រព័ន្ធគោល 10 គឺ \(1\text{ KB} = 10^3\text{ Bytes}\)។ គណនាផលដករវាងខ្នាតទាំងពីរ៖', NULL, '["\\(100\\text{ Bytes}\\)", "\\(10\\text{ Bytes}\\)", "\\(0\\text{ Bytes}\\)", "\\(24\\text{ Bytes}\\)"]', 3, NULL, 3, 'mcq', '\(1\text{ KiB} = 2^{10} = 1\,024\text{ Bytes}\) និង \(1\text{ KB} = 1\,000\text{ Bytes} \implies 1\,024 - 1\,000 = 24\text{ Bytes}\)។', 'ចំនួន', 'pisa', 1, '10', 'ចំនួន', 'ជំពូកទី 2 : តក្កវិទ្យា សំណុំ និងចំនួន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10736, 'ប្រព័ន្ធកំណត់ទីតាំង GPS គណនាចម្ងាយពីផ្កាយរណបមកស្ថានីយតាមរូបមន្ត \(d = \sqrt{x^2 + y^2 + z^2}\) គីឡូម៉ែត្រ។ បើកូអរដោនេគឺ \((3, 4, 12)\text{ km}\) នោះចម្ងាយ \(d\) គឺ៖', NULL, '["\\(13\\text{ km}\\)", "\\(17\\text{ km}\\)", "\\(15\\text{ km}\\)", "\\(19\\text{ km}\\)"]', 0, NULL, 3, 'mcq', '\(d = \sqrt{3^2 + 4^2 + 12^2} = \sqrt{9 + 16 + 144} = \sqrt{169} = 13\text{ km}\)។', 'ចំនួន', 'pisa', 1, '10', 'ចំនួន', 'ជំពូកទី 2 : តក្កវិទ្យា សំណុំ និងចំនួន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10737, 'ដោះស្រាយសមីការតម្លៃដាច់ខាត \(|2x - 1| = 7\) ក្នុងសំណុំចំនួនពិត \(\mathbb{R}\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ថ្លែងលក្ខណៈតម្លៃដាច់ខាត \(|A| = k \iff A = k\) ឬ \(A = -k\) (1 ពិន្ទុ)
បំបែកករណីទីមួយ \(2x - 1 = 7 \implies 2x = 8 \implies x = 4\) (2 ពិន្ទុ)
បំបែកករណីទីពីរ \(2x - 1 = -7 \implies 2x = -6 \implies x = -3\) (1 ពិន្ទុ)
សន្និដ្ឋានសំណុំឫសនៃសមីការគឺ \(x = 4\) ឬ \(x = -3\) (1 ពិន្ទុ)', 'ចំនួន', 'easy', 0, '10', 'ចំនួន', 'ជំពូកទី 2 : តក្កវិទ្យា សំណុំ និងចំនួន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10738, 'គណនាតម្លៃនៃកន្សោមរ៉ាឌីកាល់ \(\sqrt{48} - \dfrac{\sqrt{27}}{2} + \dfrac{1}{\sqrt{12}}\)។', NULL, '[]', 0, NULL, 5, 'writing', 'សម្រួលតួទីមួយ \(\sqrt{48} = \sqrt{16 \times 3} = 4\sqrt{3}\) (1 ពិន្ទុ)
សម្រួលតួទីពីរ \(\dfrac{\sqrt{27}}{2} = \dfrac{3\sqrt{3}}{2}\) (1 ពិន្ទុ)
បំបាត់រ៉ាឌីកាល់តួទីបី \(\dfrac{1}{\sqrt{12}} = \dfrac{1}{2\sqrt{3}} = \dfrac{\sqrt{3}}{6}\) (1 ពិន្ទុ)
តម្រូវភាគបែងរួម 6 ៖ \(\dfrac{24\sqrt{3} - 9\sqrt{3} + \sqrt{3}}{6} = \dfrac{16\sqrt{3}}{6}\) (1 ពិន្ទុ)
សម្រួលប្រភាគចុងក្រោយ \(\dfrac{8\sqrt{3}}{3}\) (1 ពិន្ទុ)', 'ចំនួន', 'medium', 0, '10', 'ចំនួន', 'ជំពូកទី 2 : តក្កវិទ្យា សំណុំ និងចំនួន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10739, 'សម្រួលកន្សោមរ៉ាឌីកាល់ពីរជាន់ \(\sqrt{7 + 2\sqrt{10}}\)។', NULL, '[]', 0, NULL, 5, 'writing', 'កំណត់ប្រព័ន្ធសមីការ \(u + v = 7\) និង \(uv = 10\) (1 ពិន្ទុ)
ដោះស្រាយរកចំនួនវិជ្ជមានទាំងពីរបាន \(u = 5\) និង \(v = 2\) (1 ពិន្ទុ)
សរសេរកន្សោមក្រោមរ៉ាឌីកាល់ជាការេនៃទ្វេធា \((\sqrt{5} + \sqrt{2})^2\) (1 ពិន្ទុ)
អនុវត្តរូបមន្ត \(\sqrt{(\sqrt{5}+\sqrt{2})^2} = |\sqrt{5}+\sqrt{2}|\) (1 ពិន្ទុ)
សន្និដ្ឋានចម្លើយចុងក្រោយ \(\sqrt{5} + \sqrt{2}\) (1 ពិន្ទុ)', 'ចំនួន', 'medium', 0, '10', 'ចំនួន', 'ជំពូកទី 2 : តក្កវិទ្យា សំណុំ និងចំនួន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10740, 'បំប្លែងចំនួន \(123_{10}\) ទៅជាចំនួនក្នុងប្រព័ន្ធរបាប់គោល 2 ដោយបង្ហាញជំហាននៃការចែក។', NULL, '[]', 0, NULL, 5, 'writing', 'ចែក \(123 \div 2 = 61\) សល់ \(1\) និង \(61 \div 2 = 30\) សល់ \(1\) (1 ពិន្ទុ)
ចែក \(30 \div 2 = 15\) សល់ \(0\) និង \(15 \div 2 = 7\) សល់ \(1\) (1 ពិន្ទុ)
ចែក \(7 \div 2 = 3\) សល់ \(1\) និង \(3 \div 2 = 1\) សល់ \(1\) (1 ពិន្ទុ)
ចែកចុងក្រោយ \(1 \div 2 = 0\) សល់ \(1\) (1 ពិន្ទុ)
អានសំណល់ពីក្រោមឡើងលើ សន្និដ្ឋាន \(123_{10} = 1\,111\,011_2\) (1 ពិន្ទុ)', 'ចំនួន', 'medium', 0, '10', 'ចំនួន', 'ជំពូកទី 2 : តក្កវិទ្យា សំណុំ និងចំនួន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10741, 'បំប្លែងចំនួន \(10\,011\,001_2\) ក្នុងប្រព័ន្ធគោល 2 ទៅជាចំនួនក្នុងប្រព័ន្ធគោល 10។', NULL, '[]', 0, NULL, 5, 'writing', 'សរសេរទម្រង់ពន្លាត \(1(2^7) + 0(2^6) + 0(2^5) + 1(2^4) + 1(2^3) + 0(2^2) + 0(2^1) + 1(2^0)\) (2 ពិន្ទុ)
គណនាស្វ័យគុណនីមួយៗ \(128 + 0 + 0 + 16 + 8 + 0 + 0 + 1\) (2 ពិន្ទុ)
បូកបញ្ចូលគ្នា សន្និដ្ឋានលទ្ធផលស្មើនឹង \(153_{10}\) (1 ពិន្ទុ)', 'ចំនួន', 'medium', 0, '10', 'ចំនួន', 'ជំពូកទី 2 : តក្កវិទ្យា សំណុំ និងចំនួន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10742, 'គេឱ្យ \(x = \dfrac{1}{\sqrt{7} - \sqrt{5}}\) និង \(y = \dfrac{1}{\sqrt{7} + \sqrt{5}}\)។
ក. គណនា \(x + y\) និង \(xy\)
ខ. ទាញរកតម្លៃនៃ \(\dfrac{y}{x} + \dfrac{x}{y}\)។', NULL, '[]', 0, NULL, 5, 'writing', 'បំបាត់រ៉ាឌីកាល់ភាគបែងបាន \(x = \dfrac{\sqrt{7}+\sqrt{5}}{2}\) និង \(y = \dfrac{\sqrt{7}-\sqrt{5}}{2}\) (1 ពិន្ទុ)
គណនាផលបូក \(x + y = \sqrt{7}\) (1 ពិន្ទុ)
គណនាផលគុណ \(xy = \dfrac{7 - 5}{4} = \dfrac{1}{2}\) (1 ពិន្ទុ)
បំប្លែងកន្សោម \(\dfrac{y}{x} + \dfrac{x}{y} = \dfrac{x^2 + y^2}{xy} = \dfrac{(x+y)^2 - 2xy}{xy}\) (1 ពិន្ទុ)
ជំនួសតម្លៃ \(\dfrac{7 - 2(1/2)}{1/2} = \dfrac{6}{1/2} = 12\) (1 ពិន្ទុ)', 'ចំនួន', 'hard', 0, '10', 'ចំនួន', 'ជំពូកទី 2 : តក្កវិទ្យា សំណុំ និងចំនួន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10743, 'បំបាត់រ៉ាឌីកាល់ពីភាគបែងនៃប្រភាគ \(\dfrac{1}{1 + \sqrt{2} - \sqrt{3}}\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ផ្តុំតួភាគបែង \((1 + \sqrt{2}) - \sqrt{3}\) រួចគុណនឹងកន្សោមឆ្លាស់ \((1 + \sqrt{2}) + \sqrt{3}\) (1 ពិន្ទុ)
ពន្លាតភាគបែង \([(1+\sqrt{2})]^2 - (\sqrt{3})^2 = (1 + 2\sqrt{2} + 2) - 3 = 2\sqrt{2}\) (1 ពិន្ទុ)
សរសេរប្រភាគមធ្យម \(\dfrac{1 + \sqrt{2} + \sqrt{3}}{2\sqrt{2}}\) (1 ពិន្ទុ)
គុណភាគយក និងភាគបែងនឹង \(\sqrt{2}\) ដើម្បីបំបាត់ \(\sqrt{2}\) (1 ពិន្ទុ)
សន្និដ្ឋានលទ្ធផលចុងក្រោយ \(\dfrac{\sqrt{2} + 2 + \sqrt{6}}{4}\) (1 ពិន្ទុ)', 'ចំនួន', 'hard', 0, '10', 'ចំនួន', 'ជំពូកទី 2 : តក្កវិទ្យា សំណុំ និងចំនួន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10744, 'គេឱ្យ \(A = \sqrt{8 - 2\sqrt{15}} + \sqrt{8 + 2\sqrt{15}}\)។ គណនាតម្លៃនៃ \(A\)។', NULL, '[]', 0, NULL, 5, 'writing', 'សម្រួល \(\sqrt{8 - 2\sqrt{15}} = \sqrt{5} - \sqrt{3}\) ព្រោះ \(5+3=8, 5\times 3=15\) (2 ពិន្ទុ)
សម្រួល \(\sqrt{8 + 2\sqrt{15}} = \sqrt{5} + \sqrt{3}\) (1 ពិន្ទុ)
បូកកន្សោមទាំងពីរ \(A = (\sqrt{5} - \sqrt{3}) + (\sqrt{5} + \sqrt{3})\) (1 ពិន្ទុ)
សន្និដ្ឋានតម្លៃ \(A = 2\sqrt{5}\) (1 ពិន្ទុ)', 'ចំនួន', 'hard', 0, '10', 'ចំនួន', 'ជំពូកទី 2 : តក្កវិទ្យា សំណុំ និងចំនួន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10745, 'ដោយប្រើវិធីសម្រាយបញ្ជាក់តាមសំណើផ្ទុយពិត ចូរបង្ហាញថា \(\sqrt{2}\) ជាចំនួនអសនិទាន។', NULL, '[]', 0, NULL, 5, 'writing', 'ឧបមាផ្ទុយថា \(\sqrt{2}\) ជាចំនួនសនិទាន នោះ \(\sqrt{2} = \dfrac{p}{q}\) ដែល \(\gcd(p, q) = 1\) (1 ពិន្ទុ)
លើកជាការេ \(2 = \dfrac{p^2}{q^2} \implies p^2 = 2q^2\) នាំឱ្យ \(p^2\) ជាចំនួនគូ ដូច្នេះ \(p\) ជាចំនួនគូ (1 ពិន្ទុ)
តាង \(p = 2k \implies (2k)^2 = 2q^2 \iff 4k^2 = 2q^2 \implies q^2 = 2k^2\) (1 ពិន្ទុ)
ទាញបាន \(q^2\) ជាចំនួនគូ នាំឱ្យ \(q\) ក៏ជាចំនួនគូដែរ (1 ពិន្ទុ)
ដោយ \(p\) និង \(q\) សុទ្ធតែជាចំនួនគូ ផ្ទុយពីការឧបមាថា \(\gcd(p, q) = 1\)។ ដូច្នេះ \(\sqrt{2}\) ជាចំនួនអសនិទាន (1 ពិន្ទុ)', 'ចំនួន', 'hard', 0, '10', 'ចំនួន', 'ជំពូកទី 2 : តក្កវិទ្យា សំណុំ និងចំនួន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10746, 'បណ្តាញអុបទិកមួយបញ្ជូនទិន្នន័យដោយបំប្លែងលេខកូដទសភាគ \(N = 217_{10}\) ទៅជាបៃ 8-bit ក្នុងប្រព័ន្ធគោល 2។
ក. បំប្លែង \(217\) ជាចំនួនគោល 2
ខ. រាប់ចំនួនប៊ីតខ្ពស់ (លេខ 1) ក្នុងបៃនោះ។', NULL, '[]', 0, NULL, 5, 'writing', 'បំបែកស្វ័យគុណនៃ 2 ៖ \(217 = 128 + 64 + 16 + 8 + 1\) (1 ពិន្ទុ)
សរសេរជាទម្រង់ស្វ័យគុណ \(2^7 + 2^6 + 2^4 + 2^3 + 2^0\) (1 ពិន្ទុ)
ទាញបានទម្រង់គោលពីរ 8-bit គឺ \(11\,011\,001_2\) (1 ពិន្ទុ)
រាប់ចំនួនលេខ 1 ក្នុងកូដ \(11\,011\,001_2\) ឃើញមាន 5 តួ (1 ពិន្ទុ)
សន្និដ្ឋានកូដគឺ \(11\,011\,001_2\) និងមាន 5 ប៊ីតខ្ពស់ (1 ពិន្ទុ)', 'ចំនួន', 'pisa', 0, '10', 'ចំនួន', 'ជំពូកទី 2 : តក្កវិទ្យា សំណុំ និងចំនួន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10747, 'ក្នុងវិស្វកម្មអគ្គិសនី អាំងប៉េដង់នៃសៀគ្វីចរន្តឆ្លាស់កំណត់ដោយរូបមន្ត \(Z = \sqrt{R^2 + (X_L - X_C)^2}\) គិតជាអូម \((\Omega)\)។ បើ \(R = 8\,\Omega\), \(X_L = 15\,\Omega\) និង \(X_C = 9\,\Omega\) ចូរគណនាអាំងប៉េដង់ \(Z\)។', NULL, '[]', 0, NULL, 5, 'writing', 'គណនាផលដកនៃរេអាក់តង់ \(X_L - X_C = 15 - 9 = 6\,\Omega\) (1 ពិន្ទុ)
លើកជាការេ \(R^2 = 8^2 = 64\) និង \((X_L - X_C)^2 = 6^2 = 36\) (1 ពិន្ទុ)
បូកបញ្ចូលគ្នា \(R^2 + (X_L - X_C)^2 = 64 + 36 = 100\) (1 ពិន្ទុ)
គណនារ៉ាឌីកាល់ \(Z = \sqrt{100} = 10\,\Omega\) (1 ពិន្ទុ)
សន្និដ្ឋានអាំងប៉េដង់នៃសៀគ្វីគឺ \(Z = 10\,\Omega\) (1 ពិន្ទុ)', 'ចំនួន', 'pisa', 0, '10', 'ចំនួន', 'ជំពូកទី 2 : តក្កវិទ្យា សំណុំ និងចំនួន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10748, 'ចម្ងាយពីចំណុចកណ្តាលរញ្ជួយដីទៅកាន់ស្ថានីយរង្វាស់ពីរមានតម្លៃ \(d_1 = \sqrt{50}\text{ km}\) និង \(d_2 = \sqrt{18}\text{ km}\)។ គណនាផលបូក \(d_1 + d_2\) និងផលដក \(d_1 - d_2\) ដោយបញ្ចេញរ៉ាឌីកាល់។', NULL, '[]', 0, NULL, 5, 'writing', 'សម្រួល \(d_1 = \sqrt{50} = \sqrt{25 \times 2} = 5\sqrt{2}\text{ km}\) (1 ពិន្ទុ)
សម្រួល \(d_2 = \sqrt{18} = \sqrt{9 \times 2} = 3\sqrt{2}\text{ km}\) (1 ពិន្ទុ)
គណនាផលបូក \(d_1 + d_2 = 5\sqrt{2} + 3\sqrt{2} = 8\sqrt{2}\text{ km}\) (1 ពិន្ទុ)
គណនាផលដក \(d_1 - d_2 = 5\sqrt{2} - 3\sqrt{2} = 2\sqrt{2}\text{ km}\) (1 ពិន្ទុ)
សន្និដ្ឋានចម្លើយទាំងពីរត្រឹមត្រូវ (1 ពិន្ទុ)', 'ចំនួន', 'pisa', 0, '10', 'ចំនួន', 'ជំពូកទី 2 : តក្កវិទ្យា សំណុំ និងចំនួន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10749, 'ល្បឿននៃសំឡេងក្នុងបរិយាកាសគិតជា \(\text{m/s}\) កំណត់ប្រហែលដោយ \(v = 20\sqrt{T}\) ដែល \(T\) ជាសីតុណ្ហភាពគិតជាកែលវិន \((\text{K})\)។ នៅសីតុណ្ហភាព \(T = 289\,\text{K}\) (ប្រហែល \(16^\circ\text{C}\)) គណនាល្បឿនសំឡេង \(v\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ជំនួសសីតុណ្ហភាព \(T = 289\) ចូលក្នុងរូបមន្ត \(v = 20\sqrt{289}\) (1 ពិន្ទុ)
គណនាឫសការេ \(\sqrt{289} = \sqrt{17^2} = 17\) (2 ពិន្ទុ)
គុណលទ្ធផល \(v = 20 \times 17 = 340\text{ m/s}\) (1 ពិន្ទុ)
សន្និដ្ឋានល្បឿនសំឡេងគឺ \(340\text{ m/s}\) (1 ពិន្ទុ)', 'ចំនួន', 'pisa', 0, '10', 'ចំនួន', 'ជំពូកទី 2 : តក្កវិទ្យា សំណុំ និងចំនួន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10750, 'ក្រុមហ៊ុនបច្ចេកវិទ្យាផលិតថាសរឹងទំហំ \(1\text{ TB} = 10^{12}\text{ Bytes}\)។ ប្រព័ន្ធប្រតិបត្តិការកុំព្យូទ័រគណនាទំហំជា \(1\text{ TiB} = 2^{40}\text{ Bytes}\)។
ក. បង្ហាញតម្លៃនៃ \(2^{40}\)
ខ. ពន្យល់មូលហេតុដែលកុំព្យូទ័របង្ហាញទំហំតូចជាងការប្រកាសរបស់ក្រុមហ៊ុន។', NULL, '[]', 0, NULL, 5, 'writing', 'គណនា \(2^{40} = (2^{10})^4 = (1\,024)^4 = 1\,099\,511\,627\,776\text{ Bytes}\) (2 ពិន្ទុ)
ប្រៀបធៀប \(10^{12} = 1\,000\,000\,000\,000\text{ Bytes} < 2^{40}\text{ Bytes}\) (1 ពិន្ទុ)
គណនាទំហំដែលកុំព្យូទ័របង្ហាញ \(\dfrac{10^{12}}{2^{40}} \approx 0.909\text{ TiB} \approx 931\text{ GiB}\) (1 ពិន្ទុ)
ពន្យល់ថាកុំព្យូទ័រប្រើប្រព័ន្ធគោល 2 (\(1\,024\)) ចំណែកក្រុមហ៊ុនផលិតប្រើប្រព័ន្ធគោល 10 (\(1\,000\)) (1 ពិន្ទុ)', 'ចំនួន', 'pisa', 0, '10', 'ចំនួន', 'ជំពូកទី 2 : តក្កវិទ្យា សំណុំ និងចំនួន', NULL, 0);
